# area: dunder_dispatch
# hypothesis: len() and iteration look up dunders on the type, so an instance-assigned __len__, an annotation-only __iter__, and a __getattr__ fallback raise TypeError while a class-defined control works.
from typing import Callable, Iterator, reveal_type


class Control:
    def __len__(self) -> int:
        return 3


class Fallback:
    def __getattr__(self, name: str) -> int:
        return 42


class Assigned:
    __iter__: Callable[[], Iterator[int]]

    def __init__(self) -> None:
        self.__len__ = lambda: 9  # expect-error: cannot assign to a method


class Inherits(Control):
    __len__ = None  # expect-error: None is not a valid __len__


def probe() -> None:
    reveal_type(len(Control()))
    print(len(Control()))
    print(Fallback().missing)  # __getattr__ applies to ordinary attribute lookup
    try:
        print(len(Fallback()))  # expect-error: __getattr__ does not supply dunders
    except TypeError as exc:
        print('fallback:', type(exc).__name__)
    try:
        print(len(Assigned()))  # expect-error: instance __len__ is ignored
    except TypeError as exc:
        print('assigned:', type(exc).__name__)
    try:
        print(len(Inherits()))  # expect-error: class __len__ set to None
    except TypeError as exc:
        print('inherits:', type(exc).__name__)
    try:
        for x in Assigned():  # expect-error: annotation-only __iter__ is not defined
            reveal_type(x)
    except TypeError as exc:
        print('iter:', type(exc).__name__)


probe()
